export const getTranscribeSpeechUrl = () => {




  return `/api/speech/transcribe`
}

/**
 * Maximum 6 MB and 30 seconds. Recordings are deleted after processing. Similarity is a text match, not an acoustic pronunciation grade.
 * @summary Transcribe a short recording and compare its text
 */
export const transcribeSpeech = async (speechTranscriptionRequest: SpeechTranscriptionRequest, options?: Parameters<typeof customFetch>[1]): Promise<SpeechTranscriptionResponse> => {
    const formData = new FormData();
formData.append(`audio`, speechTranscriptionRequest.audio);
formData.append(`expectedText`, speechTranscriptionRequest.expectedText);
formData.append(`language`, speechTranscriptionRequest.language);

  return customFetch<SpeechTranscriptionResponse>(getTranscribeSpeechUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





